package sessionread

import "testing"

func TestPHPGoldenHashes(t *testing.T) {
	// Generated by the existing PHP autosaveHash / tahsinFingerprint functions.
	if hash([]any{"ibu", int64(3), int64(2), "2026-10-18", true, []int64{10, 11}}) != "1bd98ff20afaddabdeffd25cc6ec6c110522519bbf2b8bd22caafc1f722a04b9" {
		t.Fatal("PHP context hash changed")
	}
	r := row{"id": int64(7), "wali_santri_id": int64(10), "halaqoh_id": nil, "tanggal": "2026-10-18", "status": "S", "alasan": "Ibu <contoh> / 😀\u2028kondisi", "created_at": "2026-10-18 08:42:00"}
	if fingerprint([]row{r}) != "6c3a0fd5543bba2f041fcaf579eaf5dc3f47d96b294d1fbbb34c01ef4f5a55a1" {
		t.Fatal("PHP Unicode/null/ordered record hash changed")
	}
}
func TestCalendarAndMissingData(t *testing.T) {
	d, _ := date("2026-10-22")
	if session(d) != "2026-10-18" || active("2026-10-04", nil) || active("2026-10-19", nil) || active("2026-10-18", map[string]bool{"2026-10-18": true}) {
		t.Fatal("Sunday or holiday rules changed")
	}
	if latest(d, map[string]bool{"2026-10-18": true}) != "2026-10-11" {
		t.Fatal("latest active session changed")
	}
	if len(missing(Payload{Status: "S"})) != 1 || len(missing(Payload{Status: "A"})) != 0 || len(missing(Payload{})) != 1 {
		t.Fatal("Blank attendance became official")
	}
	p := Payload{Status: "H", Material: "Iqro", Level: "3", PageFrom: "10", PageTo: "9", Result: "Lulus"}
	if len(missing(p)) != 1 {
		t.Fatal("Reverse range accepted")
	}
	p.PageTo = "11"
	if len(missing(p)) != 0 {
		t.Fatal("Complete range rejected")
	}
}
